  getExtentAttr(): Attribute {
    return this.prim.getAttr(UsdGeomTokens.extent)!
  }
  createExtentAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdGeomTokens.extent, "float3[]", false, "varying", defaultValue, writeSparsely)
  }

