        if (width === undefined || length === undefined || axis === undefined) return null
        const halfWidth = Math.fround(width * 0.5), halfLength = Math.fround(length * 0.5)
        const max: [number, number, number] = axis === 'X' ? [0, halfLength, halfWidth]
          : axis === 'Y' ? [halfWidth, 0, halfLength] : [halfWidth, halfLength, 0]
        extent = [[-max[0], -max[1], -max[2]], max]
        break
